import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      addThought({ id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() });
      setResult({ ...ai, user_text:text });
    } catch { setError('Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{setResult(null);setText('');}} setPage={setPage}/>;

  return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, position:'relative', overflow:'hidden' }}>

      {/* ── POSTER LAYOUT ── */}

      {/* Top metadata bar — like RECEIVED reference */}
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'22px 22px 0', position:'relative', zIndex:3 }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Spiral</span>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', color:'rgba(17,16,16,0.25)', textTransform:'uppercase' }}>
          {streak > 0 ? `${streak} dagar` : 'KBT · AI'}
        </span>
      </div>

      {/* Massive first line — sits ABOVE orb */}
      <div style={{ padding:'16px 20px 0', position:'relative', zIndex:3, lineHeight:0.82 }}>
        <div style={{ fontSize:'clamp(68px,20vw,120px)', fontWeight:900, letterSpacing:'-0.055em', color:'#111010', textTransform:'uppercase', lineHeight:0.82 }}>
          VAD
        </div>
      </div>

      {/* Orb — overlaps between lines, like "glass." reference */}
      <div style={{ position:'relative', zIndex:2, marginTop:'-12px', display:'flex', justifyContent:'flex-end', paddingRight:'8%', pointerEvents:'none', animation:'fadeIn 1s ease both' }}>
        <MeshSphere size={280} speed={0.38} distort={0.42} hue1={195} hue2={212} />
      </div>

      {/* Second massive line — sits BELOW orb, orb cuts through */}
      <div style={{ padding:'0 20px', position:'relative', zIndex:3, marginTop:'-80px', lineHeight:0.82 }}>
        <div style={{ fontSize:'clamp(68px,20vw,120px)', fontWeight:900, letterSpacing:'-0.055em', color:'#111010', textTransform:'uppercase', lineHeight:0.82 }}>
          SNURRAR
        </div>
        <div style={{ fontSize:'clamp(52px,15vw,90px)', fontWeight:300, letterSpacing:'-0.04em', color:'rgba(17,16,16,0.25)', textTransform:'uppercase', lineHeight:0.88, fontStyle:'italic' }}>
          just nu?
        </div>
      </div>

      {/* Thin rule */}
      <div style={{ margin:'28px 20px 20px', height:1, background:'rgba(17,16,16,0.1)', position:'relative', zIndex:3 }} />

      {/* Input section */}
      <div style={{ padding:'0 20px', position:'relative', zIndex:3, animation:'fadeUp .8s .3s both' }}>

        <div style={{ position:'relative', marginBottom:10 }}>
          <textarea
            value={text} onChange={e => setText(e.target.value)} maxLength={1000}
            placeholder="Skriv vad du tänker..."
            style={{
              width:'100%', minHeight:96,
              background:'rgba(17,16,16,0.05)',
              border:'1px solid rgba(17,16,16,0.1)',
              borderRadius:16, padding:'14px 16px',
              color:'#111010', fontSize:15, fontWeight:300,
              lineHeight:1.78, resize:'none', outline:'none',
            }}
          />
        </div>

        <div style={{ display:'flex', gap:8, alignItems:'center' }}>
          <button onClick={submit} disabled={!text.trim()||loading}
            style={{ flex:1, padding:'14px 20px', borderRadius:100,
              background: text.trim()&&!loading ? '#111010' : 'rgba(17,16,16,0.08)',
              color: text.trim()&&!loading ? '#f0ede8' : 'rgba(17,16,16,0.28)',
              fontSize:13, fontWeight:700, border:'none', transition:'all .25s',
              boxShadow: text.trim()&&!loading ? '0 4px 20px rgba(0,0,0,0.15)' : 'none',
            }}>
            {loading
              ? <span style={{ display:'flex',alignItems:'center',justifyContent:'center',gap:8 }}>
                  <span style={{ width:10,height:10,border:'2px solid rgba(240,237,232,0.3)',borderTopColor:'#f0ede8',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>
                  Analyserar
                </span>
              : 'Analysera →'}
          </button>
          <button onClick={() => setPage('checkin')}
            style={{ padding:'14px 16px', borderRadius:100, background:'rgba(17,16,16,0.06)', border:'1px solid rgba(17,16,16,0.1)', color:'rgba(17,16,16,0.5)', fontSize:13, transition:'all .2s' }}>
            Check-in
          </button>
        </div>

        {error && <p style={{ fontSize:12, color:'rgba(180,60,60,0.75)', marginTop:8 }}>{error}</p>}
      </div>
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {
  return (
    <div style={{ minHeight:'100vh', background:'#f0ede8', paddingBottom:96, overflow:'hidden', position:'relative' }}>

      {/* Top */}
      <div style={{ display:'flex', justifyContent:'space-between', padding:'22px 22px 0', position:'relative', zIndex:3 }}>
        <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>Spiral · Analys</span>
        <button onClick={onBack} style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)' }}>← Tillbaka</button>
      </div>

      {/* Big trap name over orb */}
      <div style={{ padding:'16px 20px 0', position:'relative', zIndex:3 }}>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(17,16,16,0.35)', marginBottom:8 }}>
          {result.trap_icon} Tankefälla
        </div>
        <div style={{ fontSize:'clamp(38px,10vw,64px)', fontWeight:900, letterSpacing:'-0.05em', lineHeight:0.88, color:'#111010', textTransform:'uppercase' }}>
          {result.trap_label}
        </div>
      </div>

      {/* Orb */}
      <div style={{ position:'relative', zIndex:2, marginTop:'-20px', display:'flex', justifyContent:'center', pointerEvents:'none' }}>
        <MeshSphere size={240} speed={0.3} distort={0.55} hue1={20} hue2={340} />
      </div>

      {/* Content */}
      <div style={{ padding:'0 20px', position:'relative', zIndex:3, marginTop:'-30px' }}>
        <p style={{ fontSize:12, color:'rgba(17,16,16,0.38)', fontStyle:'italic', lineHeight:1.7, marginBottom:20, paddingLeft:12, borderLeft:'2px solid rgba(17,16,16,0.12)' }}>
          "{text.slice(0,100)}{text.length>100?'...':''}"
        </p>

        <div style={{ height:1, background:'rgba(17,16,16,0.08)', marginBottom:16 }} />

        {[
          { label:'Vad händer',  body:result.description },
          { label:'Omramning',   body:result.reframe },
          { label:'Övning',      body:result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} style={{ marginBottom:12, padding:'14px 16px', background:'rgba(17,16,16,0.04)', border:'1px solid rgba(17,16,16,0.07)', borderRadius:14 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.16em', textTransform:'uppercase', color:'rgba(17,16,16,0.32)', marginBottom:7 }}>{label}</p>
            <p style={{ fontSize:14, color:'rgba(17,16,16,0.72)', lineHeight:1.82, fontWeight:300 }}>{body}</p>
          </div>
        ))}

        <button onClick={() => setPage('breathing')}
          style={{ width:'100%', padding:'13px', background:'rgba(17,16,16,0.05)', border:'1px solid rgba(17,16,16,0.09)', borderRadius:14, color:'rgba(17,16,16,0.5)', fontSize:13, marginTop:4 }}>
          🫁 Andningsövning
        </button>
      </div>
    </div>
  );
}
